// Extract job_id from query params
const input = $input.first().json;
const query = input.query || {};

const jobId = query.job_id || null;

if (!jobId) {
  return [{
    json: {
      success: false,
      error: {
        code: 400,
        message: 'Le paramètre "job_id" est requis',
        status: 'BAD_REQUEST'
      }
    }
  }];
}

return [{
  json: {
    valid: true,
    jobId: jobId
  }
}];

// Format job response
const input = $input.first().json;
const jobId = $('Parse Parameters').first().json.jobId;

const data = input.body || input;
const statusCode = input.statusCode || 200;

// API error
if (statusCode >= 400) {
  return [{
    json: {
      success: false,
      error: {
        code: statusCode,
        message: data.error?.message || data.message || 'Job non trouvé',
        status: 'JOB_NOT_FOUND'
      },
      _needsResultFetch: false
    }
  }];
}

// If job is completed, we need to fetch the stored result
if (data.status === 'completed') {
  return [{
    json: {
      ...data,
      jobId: jobId,
      _needsResultFetch: true
    }
  }];
}

// Return API response as-is for in_progress
return [{ json: { ...data, _needsResultFetch: false } }];

// Combine job data with stored result
const input = $input.first().json;
const jobData = $('Check Job Status').first().json;

const resultData = input.body || input;
const storedResult = resultData.result;

// If no stored result, return job data as-is
if (!storedResult || !resultData.found) {
  const response = { ...jobData };
  delete response._needsResultFetch;
  delete response.jobId;
  return [{ json: response }];
}

// Build full response with translation
const segments = storedResult.segments || [];
const firstSegment = segments[0] || {};

const response = {
  job_id: jobData.job_id || jobData.jobId,
  status: 'completed',
  traite: jobData.traite || storedResult.traite,
  page: jobData.page || storedResult.page,
  progress: jobData.progress || {
    current: segments.length,
    total: segments.length,
    percentage: 100
  },
  duration_seconds: jobData.duration_seconds,
  // Translation data (for single segment)
  translation: segments.length === 1 ? {
    original: firstSegment.original,
    final: firstSegment.translation,
    intermediate_en: firstSegment.intermediate_en,
    source_language: storedResult.sourceLanguage,
    target_language: storedResult.targetLanguage,
    pivot_used: storedResult.pivotUsed,
    claude_translation: firstSegment.claude_translation,
    gpt_suggestion: firstSegment.gpt_translation
  } : null,
  // For multi-segment, provide all translations
  translations: segments.length > 1 ? segments.map(s => ({
    segment_index: s.segment_index,
    original: s.original,
    translation: s.translation,
    confidence: s.confidence
  })) : null,
  verification: {
    approved: firstSegment.approved,
    confidence: firstSegment.confidence,
    requires_vote: firstSegment.requires_vote
  },
  tokens: {
    claude: storedResult.totalClaudeTokens,
    gpt: storedResult.totalGptTokens,
    total: {
      input_tokens: (storedResult.totalClaudeTokens?.input_tokens || 0) + (storedResult.totalGptTokens?.input_tokens || 0),
      output_tokens: (storedResult.totalClaudeTokens?.output_tokens || 0) + (storedResult.totalGptTokens?.output_tokens || 0),
      total_tokens: (storedResult.totalClaudeTokens?.total_tokens || 0) + (storedResult.totalGptTokens?.total_tokens || 0)
    }
  },
  requires_vote: firstSegment.requires_vote || false
};

return [{ json: response }];

// Clean up and pass through
const input = $input.first().json;
const response = { ...input };
delete response._needsResultFetch;
delete response.jobId;
return [{ json: response }];
